export const speakAsBoss = (bossId: string, text: string, helpers: BossHelpers) => {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    switch (bossId) {
      case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
      case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
      case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
      case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
      case 'Drug Trade Dale': utterance.pitch = 1.8; utterance.rate = 1.1; break;
      default: utterance.pitch = 1.0; utterance.rate = 1.0;
    }
    utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
    helpers.setBossVulgarity(text, BOSS_VULGARITY_DURATION);
  }
};

export const checkIsWeakness = (stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (!p) {
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
    if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
    if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
    return false;
  }
  if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
  if (stageId === 'Victor Volcano' && p.isTsunami) return true;
  if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Ernie Earthquake' && p.isIce) return true;
  return false;
};

export const getBossDamage = (boss: Enemy, stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) return 150;
  const isWeak = checkIsWeakness(stageId, currentWeapon, p);
  if (isWeak) return 100;
  if (currentWeapon === 'TASER') return Math.floor(BULLET_DAMAGE * TASER_BOSS_DAMAGE_REDUCTION);
  return BULLET_DAMAGE;
};

export const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean, stageId: string | null, currentWeapon: WeaponType, state: any, helpers: BossHelpers) => {
  if (state.bossExplosionTimer > 0) return;
  const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };

  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) {
    speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][0], helpers);
  }

  state.bossVolcanoes = [];
  state.bossVolcanoTelegraphs = [];
  state.bossPoopTelegraphs = [];
  state.bossSteamExplosions = [];
  state.ernieVibrationTimer = 0;
  state.projectiles = [];
  state.tsunamiActive = false;
  state.tsunamiX = -1;

  if (wasWeakness) {
    state.bossExplosionTimer = 180; 
    state.bossExplosionPos = pos;
    helpers.spawnDeathShower(state.bossExplosionPos, playerFacing, 35, true, 120); 
  } else {
    helpers.spawnDeathShower(pos, playerFacing, 6, true, 45);
    helpers.onBossDeath(); 
    state.victoryString = "V"; 
    state.postVictoryTimer = 0;
  }
  state.player.killSatisfactionTimer = 0;
  state.player.bossKillSatisfactionTimer = 240; 
  state.arenaLocked = false;

  let cat: VulgarityType = 'gun_kill';
  if (currentWeapon === 'BOULDER') cat = 'boulder_kill';
  else if (currentWeapon === 'SHOTGUN') cat = 'shotgun_kill';
  else if (currentWeapon === 'FLAMETHROWER') cat = 'flamethrower_kill';
  else if (currentWeapon === 'TSUNAMI') cat = 'tsunami_kill';
  helpers.speakVulgarity(cat);
};

export const updateBossAI = (
  boss: Enemy, 
  stageId: string | null, 
  player: Player, 
  currentWeapon: WeaponType, 
  invincibilityEnabled: boolean,
  state: any, 
  helpers: BossHelpers
) => {
  boss.stateTimer = (boss.stateTimer || 0) - 1;
  const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1;
  const healthPct = (boss.health / boss.maxHealth) * 100;

  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) {
    if (healthPct <= 75 && !boss.said75) { boss.said75 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][75], helpers); }
    if (healthPct <= 50 && !boss.said50) { boss.said50 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][50], helpers); }
    if (healthPct <= 25 && !boss.said25) { boss.said25 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][25], helpers); }
  }

  if (stageId === 'Drug Trade Dale') {
    handleDaleAI(boss, player, invincibilityEnabled, state, helpers);
  } else if (stageId === 'Hector Hurricane') {
    handleHectorAI(boss, player, invincibilityEnabled, state, helpers);
  } else if (stageId === 'Artie Avalanche') {
    handleArtieAI(boss, player, state, helpers);
  } else if (stageId === 'Ernie Earthquake') {
    handleErnieAI(boss, player, state, helpers);
  } else if (stageId === 'Victor Volcano') {
    handleVictorAI(boss, player, healthPct, state, helpers);
  }

  if (boss.bossState !== 'stunned_drop' && stageId !== 'Drug Trade Dale') {
    const gravityMult = (stageId === 'Artie Avalanche' || (stageId === 'Ernie Earthquake' && !boss.isGroundedBoss)) ? 0.5 : 1.0;
    boss.vel.y += GRAVITY * gravityMult; 
    boss.pos.x += boss.vel.x; 
    const prevY = boss.pos.y; 
    boss.pos.y += boss.vel.y;
    boss.pos.x = Math.max(BOSS_DOOR_X + 10, Math.min(8000 - boss.width - 10, boss.pos.x));
    if (boss.pos.y < 100) { boss.pos.y = 100; boss.vel.y = 0; }

    let bossGroundedOnBlock = false;
    if (boss.vel.y >= 0) {
      for (const b of state.blocks) {
        if (b.type === 'platform' || b.type === 'ground') {
          if (boss.pos.x < b.x + b.w && boss.pos.x + boss.width > b.x && prevY + boss.height <= b.y && boss.pos.y + boss.height >= b.y) {
            boss.pos.y = b.y - boss.height;
            if (stageId === 'Ernie Earthquake' && prevY < b.y - boss.height) { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); }
            boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; bossGroundedOnBlock = true;
            if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle';
            break;
          }
        }
      }
    }
    if (!bossGroundedOnBlock) {
      if (boss.pos.y > 470) {
        boss.pos.y = 470; 
        if (prevY < 470 && boss.vel.y > 0 && stageId === 'Ernie Earthquake') {
          helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); 
          helpers.addProjectile({ id: `b-ernie-land-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true });
        }
        boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true;
        if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle';
      } else boss.isGroundedBoss = false;
    }
  } else if (boss.bossState === 'stunned_drop') { 
    boss.vel.y += GRAVITY * 1.5; boss.pos.y += boss.vel.y; 
    if (boss.pos.y > 470) { boss.pos.y = 470; boss.vel.y = 0; boss.isGroundedBoss = true; if (boss.stateTimer! > 30) boss.stateTimer = 30; } 
  }
};

const handleDaleAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'idle' && boss.stateTimer! <= 0) {
    boss.bossState = 'truck_incoming';
    boss.stateTimer = 100;
    boss.truckX = BOSS_DOOR_X - 600;
    boss.truckActive = true;
    helpers.playGunSound('horn');
  } else if (boss.bossState === 'truck_incoming') {
    boss.truckX! += DALE_TRUCK_SPEED; 
    const tx = boss.truckX!, ty = 400, tw = 350, th = 150;
    if (player.pos.x < tx + tw && player.pos.x + player.width > tx && player.pos.y < ty + th && player.pos.y + player.height > ty && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
      player.health -= DALE_TRUCK_DAMAGE; 
      player.invincibilityTimer = 60;
      player.pushbackTimer = 40;
      player.vel = DALE_PUSHBACK_VEL;
      helpers.speakVulgarity('hurt');
    }
    state.projectiles.forEach((p: Projectile) => {
      if (p.isMethBarrel && p.health > 0) {
        if (p.pos.x < tx + tw && p.pos.x + p.width > tx && p.pos.y < ty + th && p.pos.y + p.height > ty) {
          p.health = -1; 
        }
      }
    });

    if (boss.truckX! > 8200) {
      boss.truckActive = false;
      boss.bossState = 'using_shipment';
      const drugs: ('cocaine' | 'speed' | 'meth')[] = ['cocaine', 'speed', 'meth'];
      boss.shipmentType = drugs[Math.floor(Math.random() * drugs.length)];
      boss.shipmentCount = boss.shipmentType === 'cocaine' ? 10 : (boss.shipmentType === 'meth' ? 5 : 1);
      boss.stateTimer = 30;
    }
  } else if (boss.bossState === 'using_shipment') {
    if (boss.stateTimer! <= 0) {
      if (boss.shipmentType === 'cocaine') {
        const rangeRoll = Math.random();
        let vx, vy;
        if (rangeRoll < 0.3) { 
          vx = -2 - Math.random() * 3;
          vy = -18 - Math.random() * 6;
        } else if (rangeRoll < 0.75) { 
          vx = -10 - Math.random() * 5;
          vy = -14 - Math.random() * 5;
        } else { 
          vx = -20 - Math.random() * 8;
          vy = -8 - Math.random() * 4;
        }

        helpers.addProjectile({ 
          id: `coke-${Date.now()}`, 
          pos: { x: boss.pos.x, y: boss.pos.y + 20 }, 
          vel: { x: vx, y: vy }, 
          width: 25, height: 25, health: 1, maxHealth: 1, 
          type: 'projectile', damage: 30, owner: 'enemy', isCocaine: true 
        });
        boss.shipmentCount!--;
        boss.stateTimer = 20;
        if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 80; }
      } else if (boss.shipmentType === 'meth') {
        helpers.addProjectile({ 
          id: `meth-${Date.now()}`, 
          pos: { x: boss.pos.x, y: boss.pos.y }, 
          vel: { x: -4 - Math.random() * 3, y: -12 }, 
          width: 40, height: 50, health: 100, maxHealth: 100, 
          type: 'projectile', damage: METH_BARREL_DAMAGE, owner: 'enemy', isMethBarrel: true, bounces: 15
        });
        boss.shipmentCount!--;
        boss.stateTimer = 45; 
        if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 100; }
      } else if (boss.shipmentType === 'speed') {
        boss.bossState = 'speed_dash';
        boss.dashCount = 8;
        boss.vel.x = -25;
        boss.stateTimer = 0;
        helpers.playGunSound('ice'); 
      }
    }
  } else if (boss.bossState === 'speed_dash') {
    boss.pos.x += boss.vel.x;
    if (boss.pos.x < BOSS_DOOR_X + 20 || boss.pos.x + boss.width > 7980) {
      boss.vel.x *= -1;
      boss.dashCount!--;
      helpers.setScreenShake(10);
      if (boss.dashCount! <= 0) {
        boss.pos.x = 7840; 
        boss.vel.x = 0;
        boss.bossState = 'idle';
        boss.stateTimer = 150;
      }
    }
  }
};

const handleHectorAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'hurricane') {
    const forceDir = (boss.pos.x + boss.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1;
    state.totalPullForceX += forceDir * HECTOR_PULL_STRENGTH_ULT;

    state.projectiles.forEach((p: Projectile) => {
      if (p.owner === 'player' && p.isBoulder) {
        const pullDir = (boss.pos.x + boss.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1;
        p.vel.x += pullDir * 1.5; 
      }
      if (p.isPoop) p.vel.x += forceDir * HECTOR_PULL_STRENGTH;
    });

    state.bossPoopTelegraphs = state.bossPoopTelegraphs.filter((t: any) => {
      t.life--;
      if (t.life <= 0) {
        const spawnLeft = t.spawnX === BOSS_DOOR_X; const velX = spawnLeft ? 12 : -12;
        helpers.addProjectile({ id: `poop-${Date.now()}`, pos: { x: t.spawnX, y: t.pos.y }, vel: { x: velX, y: (Math.random()-0.5)*3 }, width: 45, height: 20, health: 1, maxHealth: 1, type: 'projectile', damage: 12, owner: 'enemy', isPoop: true, spawnX: t.spawnX });
        return false;
      }
      return true;
    });

    if (state.frame % 90 === 0) { 
      const spawnLeft = forceDir > 0, spawnX = spawnLeft ? BOSS_DOOR_X : 8000;
      const r = Math.random(); let spawnY;
      if (r < 0.33) spawnY = 510; else if (r < 0.66) spawnY = 498; else spawnY = 440;
      helpers.addPoopTelegraph({ pos: { x: spawnX, y: spawnY }, life: 60, spawnX: spawnX });
    }

    if (Math.abs((boss.pos.x + boss.width/2) - (player.pos.x + player.width/2)) < 300 && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
      player.health -= 4; if (player.health > 0) { player.invincibilityTimer = 25; player.pushbackTimer = 2; helpers.speakVulgarity('hurt'); }
    }
    if (boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; helpers.clearPoopTelegraphs(); }
  } else if (boss.bossState === 'jumping') {
    if (boss.isGroundedBoss) { boss.bossState = 'hurricane'; boss.stateTimer = 300; boss.vel.x = 0; }
  } else if (boss.stateTimer! <= 0) {
    boss.bossState = 'jumping'; boss.vel.y = -22 - Math.random() * 4;
    const targetX = boss.pos.x > 7600 ? 7300 : 7900; boss.vel.x = (targetX - boss.pos.x) * 0.035;
  }
};

const handleArtieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.shootTimer > 0) boss.shootTimer--;
  if (boss.isGroundedBoss && Math.abs(boss.vel.x) < 0.5) boss.sideTimer = (boss.sideTimer || 0) + 1; else boss.sideTimer = 0;
  if ((boss.stateTimer! <= 0 || (boss.sideTimer || 0) > 175) && boss.isGroundedBoss) {
    const r = Math.random(); const mustMove = (boss.sideTimer || 0) > 120;
    if (r < 0.35 || (mustMove && r < 0.6)) { 
      boss.vel.y = -13 - Math.random() * 3; boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * (4 + Math.random() * 2); boss.stateTimer = 70; boss.bossState = 'jumping'; boss.sideTimer = 0; 
    } else if (r < 0.70 && boss.shootTimer <= 0 && !mustMove) { 
      const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60;
      helpers.addProjectile({ id: `ice-big-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
      boss.shootTimer = 60; boss.stateTimer = 80; boss.bossState = 'attacking';
    } else { boss.vel.x = (player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1) * 7.5; boss.stateTimer = 65; boss.bossState = 'attacking'; boss.sideTimer = 0; }
  }
  if (boss.bossState === 'jumping' && !boss.isGroundedBoss && boss.shootTimer <= 0) {
    if (Math.abs(boss.vel.y) < 2 && boss.stateTimer! > 20 && Math.random() < 0.08) { 
      const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60;
      helpers.addProjectile({ id: `ice-big-air-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true });
      boss.shootTimer = 60; boss.stateTimer = 50; 
    }
  }
  if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const handleErnieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'stunned_drop') { if (boss.isGroundedBoss && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; boss.rotation = 0; } } 
  else if (boss.stateTimer! <= 0) {
    const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1;
    boss.vel.y = -12; boss.vel.x = (player.pos.x - boss.pos.x) * 0.03; boss.stateTimer = 180; 
    helpers.addProjectile({ id: `b-ernie-jump-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true });
  }
};

const handleVictorAI = (boss: Enemy, player: Player, healthPct: number, state: any, helpers: BossHelpers) => {
  const victorMidX = boss.pos.x + boss.width / 2;
  if (boss.bossState === 'attacking') {
    boss.vel.x = 0; if (state.bossVolcanoes.length === 0 && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; }
  } else if (boss.bossState === 'telegraphing') {
    boss.vel.x = 0;
    if (boss.stateTimer! <= 0) {
      boss.bossState = 'attacking'; boss.stateTimer = 180;
      state.bossVolcanoTelegraphs.forEach((t: Volcano) => helpers.addVolcano({ pos: t.pos, life: 180, type: t.type }));
      helpers.clearVolcanoTelegraphs();
    }
  } else if (boss.bossState === 'jumping') {
    if (boss.isGroundedBoss) {
      boss.bossState = 'telegraphing'; boss.stateTimer = 60;
      helpers.clearVolcanoTelegraphs();
      const newSide = (state.victorWallSide + 1) % 2;
      helpers.setVictorWallSide(newSide);
      // Wall turrets exactly on walls
      helpers.addVolcanoTelegraph({ pos: { x: newSide === 0 ? BOSS_DOOR_X : 8000, y: 250 + Math.random() * 200 }, life: 60, type: 'wall' });

      const groundCount = healthPct > 50 ? 1 : 2;
      const groundXs: number[] = [];
      for(let i=0; i<groundCount; i++) {
        let tx = 0, attempts = 0, valid = false;
        while(!valid && attempts < 20) {
          tx = BOSS_DOOR_X + 150 + Math.random() * 500;
          valid = Math.abs(tx - victorMidX) > 150; 
          if (valid) for (const existingX of groundXs) if (Math.abs(tx - existingX) < 100) { valid = false; break; }
          attempts++;
        }
        groundXs.push(tx);
        // Ground turrets exactly on ground line (y=550)
        helpers.addVolcanoTelegraph({ pos: { x: Math.max(BOSS_DOOR_X + 50, Math.min(7900, tx)), y: 550 }, life: 60, type: 'ground' });
      }
    }
  } else if (boss.stateTimer! <= 0) {
    boss.vel.y = -20 - Math.random() * 5;
    const platforms = state.blocks.filter((b: any) => b.type === 'platform' && b.x > BOSS_DOOR_X);
    if (platforms.length > 0) {
      const targetPlate = platforms[Math.floor(Math.random() * platforms.length)];
      boss.vel.x = (targetPlate.x + targetPlate.w / 2 - victorMidX) * 0.04;
    } else { boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * 4 + (Math.random()-0.5)*2; }
    boss.bossState = 'jumping'; boss.stateTimer = 60;
  }
  if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const drawBoss = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null, frame: number) => {
  const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
  if (e.rotation) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation); ctx.translate(-width / 2, -height / 2); }
  if (id === 'Drug Trade Dale' && e.bossState === 'speed_dash') {
    ctx.filter = `hue-rotate(${frame * 10}deg) saturate(3)`;
  }
  switch (id) {
    case 'Artie Avalanche': 
      ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); 
      ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); 
      ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); 
      break;
    case 'Victor Volcano': 
      ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); 
      const lOff = (e.bossState === 'attacking' || e.bossState === 'telegraphing') ? Math.sin(frame * 0.5) * 6 : 0; 
      ctx.fillStyle = '#C62828'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3 + lOff, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); 
      ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2 + lOff, width * 0.6, height * 0.1); 
      break;
    case 'Ernie Earthquake': 
      ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7); 
      ctx.fillStyle = '#FF5252'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); 
      break;
    case 'Hector Hurricane': 
      ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); 
      ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); 
      break;
    case 'Drug Trade Dale': 
      ctx.fillStyle = '#2C3E50'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height);
      ctx.fillStyle = '#8E44AD'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4);
      ctx.fillStyle = 'gold'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.25, width * 0.2, 0, Math.PI * 2); ctx.fill();
      if (e.bossState === 'using_shipment') ctx.fillStyle = '#fff'; ctx.fillRect(width * 0.1, -20, width * 0.8, 20); 
      if (e.bossState === 'speed_dash') {
        ctx.save(); ctx.translate(width * 0.2, height * 0.3); ctx.rotate(-0.5);
        ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(0, -2, 16, 4);
        ctx.fillStyle = 'red'; ctx.fillRect(16, -4, 6, 8); ctx.restore();
      }
      break;
    default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
  }
  ctx.restore();
};

export const drawDaleDrugs = (ctx: CanvasRenderingContext2D, e: Enemy) => {
  if (e.bossState === 'using_shipment' && e.shipmentCount! > 0) {
    const stackX = e.pos.x - 60, groundY = 550;
    ctx.save();
    for (let i = 0; i < e.shipmentCount!; i++) {
      const row = Math.floor(i / 2), col = i % 2;
      if (e.shipmentType === 'cocaine') {
        ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1;
        const bx = stackX + (col * 20) + (row * 3), by = groundY - (row * 15) - 20;
        ctx.fillRect(bx, by, 18, 18); ctx.strokeRect(bx, by, 18, 18);
      } else if (e.shipmentType === 'meth') {
        ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2;
        const bx = stackX + (col * 30) - 10, by = groundY - (row * 35) - 40;
        ctx.fillRect(bx, by, 30, 40); ctx.strokeRect(bx, by, 30, 40);
        ctx.fillStyle = '#FFD700'; ctx.font = '8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", bx + 15, by + 25);
      } else if (e.shipmentType === 'speed' && e.stateTimer! > 0) {
        const bx = stackX, by = groundY - 20;
        ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(bx + 5, by, 15, 4);
        ctx.fillStyle = 'red'; ctx.fillRect(bx, by - 2, 6, 8);
      }
    }
    ctx.restore();
  }
};

import { 
  Player, Projectile, Vector2, WeaponType, Particle, Enemy, DamageNumber, Vector2 as Vec2, VulgarityType
} from './types';
import { 
  BULLET_DAMAGE, BOULDER_DAMAGE, BOULDER_SPEED, SHOTGUN_DAMAGE, 
  SHOTGUN_COOLDOWN, SHOTGUN_FREEZE_TIME, FLAMETHROWER_DAMAGE, 
  FLAMETHROWER_RANGE, TSUNAMI_COOLDOWN, COLORS, PARTICLE_PALETTES,
  MAX_AMMO, TASER_RANGE, CANVAS_WIDTH, GUN_COOLDOWN, GUN_VELOCITY,
  BOULDER_COOLDOWN, SHOTGUN_PELLET_COUNT, NEEDLE_DAMAGE, NEEDLE_COOLDOWN,
  ENEMY_UPPERCUT_DAMAGE, BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, GRAVITY
} from './constants';
import * as BossLogic from './boss';

export interface WeaponHelpers {
  addProjectile: (p: Projectile) => void;
  addParticle: (p: Particle) => void;
  playGunSound: (type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite') => void;
  spawnExplosion: (pos: Vec2, color: string, count: number, baseVelX?: number, spread?: number) => void;
  spawnDamageNumber: (pos: Vec2, value: number, isCritical?: boolean) => void;
  spawnGlassShatter: (pos: Vec2) => void;
  spawnIceShatter: (pos: Vec2) => void;
  spawnSteamExplosionParticles: (pos: Vec2, count?: number) => void;
  spawnDeathShower: (pos: Vec2, facing: number, multiplier?: number, isBossDeath?: boolean, spreadOverride?: number) => void;
  spawnPickup: (pos: Vec2) => void;
  speakVulgarity: (category: VulgarityType) => void;
  setScreenShake: (duration: number) => void;
  triggerBossDeath: (boss: Enemy, facing: number, wasWeakness: boolean) => void;
  spawnRockShatter: (pos: Vec2) => void;
  spawnBoulderShrapnel: (pos: Vec2, count: number, dir: number) => void;
  spawnMethExplosion: (pos: Vec2, count?: number) => void;
}

export const fireWeapon = (
  player: Player, 
  state: any, 
  helpers: WeaponHelpers, 
  isMoveUp: boolean,
  isMoveDown: boolean,
  infiniteAmmo: boolean
) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = isDucking ? pos.y + 45 : pos.y + 25;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ 
      id: `p-${Date.now()}`, 
      pos: { x: shootX, y: shootY }, 
      vel: { x: facing * GUN_VELOCITY, y: 0 }, 
      width: 16, height: 6, health: 1, maxHealth: 1, 
      type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' 
    });
    player.shootCooldown = GUN_COOLDOWN;
    helpers.playGunSound('gun');
  } 
  else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0;
      const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ 
        id: `b-${Date.now()}`, 
        pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, 
        vel: { x: vx, y: vy }, 
        width: 48, height: 48, health: 1, maxHealth: 1, 
        type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true 
      });
      player.shootCooldown = BOULDER_COOLDOWN;
      if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } 
  else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15;
      const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ 
        id: `pellet-${Date.now()}-${i}`, 
        pos: { x: shootX, y: shootY }, 
        vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, 
        width: 10, height: 10, health: 1, maxHealth: 1, 
        type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true 
      });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN;
    helpers.playGunSound('ice');
    if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } 
  else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ 
      id: `dart-${Date.now()}`, 
      pos: { x: shootX, y: shootY }, 
      vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, 
      width: 20, height: 4, health: 1, maxHealth: 1, 
      type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true 
    });
    player.shootCooldown = NEEDLE_COOLDOWN;
    helpers.playGunSound('dart');
    if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } 
  else if (currentWeapon === 'FLAMETHROWER') {
    if (state.frame % 2 === 0) {
      if (!infiniteAmmo) player.weaponAmmo['FLAMETHROWER']--;
      helpers.playGunSound('flame');

      const charge = player.flamethrowerCharge || 0;
      const chargeProgress = Math.min(1.0, charge / 120); // 120 frames = 2 seconds
      const dynamicRange = FLAMETHROWER_RANGE + (chargeProgress * (800 - FLAMETHROWER_RANGE));

      const aimAngle = isMoveUp ? -Math.PI/4 : (isMoveDown ? Math.PI/4 : 0);

      for (let i = 0; i < 6; i++) {
        const pAngle = aimAngle + (Math.random() - 0.5) * 0.6;
        const speed = (8 + Math.random() * 8) * (1 + chargeProgress * 0.5);
        helpers.addParticle({ 
          pos: { x: pos.x + (facing === 1 ? width - 5 : 5), y: pos.y + 30 }, 
          vel: { 
            x: Math.cos(pAngle) * facing * speed + player.vel.x, 
            y: Math.sin(pAngle) * speed + (isMoveUp ? -4 : (isMoveDown ? 4 : 0)) 
          }, 
          life: (15 + Math.random() * 20) * (1 + chargeProgress * 1.5), 
          color: PARTICLE_PALETTES.FIRE[Math.floor(Math.random() * PARTICLE_PALETTES.FIRE.length)], 
          size: (8 + Math.random() * 12) * (1 + chargeProgress * 0.5)
        });
      }

      const fRect = { 
        x: facing === 1 ? pos.x + width : pos.x - dynamicRange, 
        y: pos.y + 10 + (isMoveUp ? -dynamicRange * 0.5 : (isMoveDown ? dynamicRange * 0.3 : 0)), 
        w: dynamicRange, 
        h: 50 + (isMoveUp || isMoveDown ? dynamicRange * 0.6 : 0)
      };

      state.projectiles.forEach((p: Projectile) => {
        if (p.owner === 'enemy' && p.pos.x < fRect.x + fRect.w && p.pos.x + p.width > fRect.x && p.pos.y < fRect.y + fRect.h && p.pos.y + p.height > fRect.y) {
          if ((p.isIce && p.width > 30) || !(p.id.startsWith('debris-') || p.id.startsWith('magma-') || (p.isBoulder && p.owner === 'enemy') || (p.isIce && p.width <= 20))) {
            p.health = 0;
            helpers.spawnExplosion(
              { x: p.pos.x + p.width/2, y: p.pos.y + p.height/2 }, 
              p.isIce ? COLORS.PROJECTILE_ICE : (p.id.startsWith('magma') ? '#FF4500' : COLORS.PROJECTILE_ENEMY), 
              Math.min(10, Math.ceil(p.width / 5)), 0, 10
            );
          }
        }
      });

      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway && e.pos.x < fRect.x + fRect.w && e.pos.x + e.width > fRect.x && e.pos.y < fRect.y + fRect.h && e.pos.y + e.height > fRect.y) {
          if (e.type === 'boss') {
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
              const dmg = BossLogic.getBossDamage(e, state.stageId, currentWeapon);
              const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon);
              e.health -= dmg;
              e.hitCooldown = 60;
              helpers.spawnDamageNumber(e.pos, dmg, isW);
              if (state.stageId === 'Artie Avalanche' && isW && e.health > 0) {
                const tx = e.pos.x < 7560 ? 7850 : 7250;
                e.vel.y = -22;
                e.vel.x = (tx - e.pos.x) / 50;
                e.bossState = 'jumping';
                e.stateTimer = 60;
              }
              if (e.health <= 0) helpers.triggerBossDeath(e, facing, isW);
            } else if (e.type === 'boss') {
              for (let i = 0; i < (state.stageId === 'Artie Avalanche' ? 4 : 2); i++) {
                helpers.addParticle({ 
                  pos: { x: e.pos.x + Math.random() * e.width, y: e.pos.y + Math.random() * e.height }, 
                  vel: { x: (Math.random() - 0.5) * 6, y: -Math.random() * 8 - 2 }, 
                  life: 15 + Math.random() * 20, 
                  color: PARTICLE_PALETTES.FIRE[Math.floor(Math.random() * PARTICLE_PALETTES.FIRE.length)], 
                  size: 6 + Math.random() * 10 
                });
              }
            }
          } else {
            e.health -= FLAMETHROWER_DAMAGE;
            helpers.spawnDamageNumber(e.pos, FLAMETHROWER_DAMAGE);
            if (e.health <= 0) {
              e.isBlownAway = true;
              e.vel = { x: facing * 5, y: -5 };
              player.killSatisfactionTimer = 60;
            }
          }
        }
      });
    }
  } 
  else if (currentWeapon === 'TSUNAMI') {
    if (!state.tsunamiActive) {
      state.tsunamiActive = true;
      state.tsunamiDir = facing;
      state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; 
      state.tsunamiX = state.tsunamiStartX;
      player.shootCooldown = TSUNAMI_COOLDOWN;
      helpers.playGunSound('tsunami');
      if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--;
    }
  }
  else if (currentWeapon === 'TASER') {
    if (!player.isTasing) {
      let nearest: (Enemy | Projectile) | null = null;
      let minDist = TASER_RANGE;
      const playerMidX = player.pos.x + player.width/2;
      const playerMidY = player.pos.y + player.height/2;

      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway) {
          const ex = e.pos.x + e.width/2;
          const ey = e.pos.y + e.height/2;
          if (ex > state.camera.x && ex < state.camera.x + CANVAS_WIDTH) {
            if ((facing === 1 && ex > playerMidX) || (facing === -1 && ex < playerMidX)) {
              const dx = ex - playerMidX;
              const dy = ey - playerMidY;
              const dist = Math.sqrt(dx*dx + dy*dy);
              if (dist < minDist) { minDist = dist; nearest = e; }
            }
          }
        }
      });

      state.projectiles.forEach((p: Projectile) => {
        if (p.isMethBarrel && p.health > 0) {
          const px = p.pos.x + p.width/2;
          const py = p.pos.y + p.height/2; // Fixed py usage
          if (px > state.camera.x && px < state.camera.x + CANVAS_WIDTH) {
            if ((facing === 1 && px > playerMidX) || (facing === -1 && px < playerMidX)) {
              const dx = px - playerMidX;
              const dy = py - playerMidY;
              const dist = Math.sqrt(dx*dx + dy*dy);
              if (dist < minDist) { minDist = dist; nearest = p; }
            }
          }
        }
      });

      player.isTasing = true;
      player.taserTimer = 0;
      if (nearest) {
        player.taserTargetId = (nearest as (Enemy | Projectile)).id;
      } else {
        player.taserTargetId = null;
      }
    }
  }
};

export const updateProjectiles = (state: any, helpers: WeaponHelpers, invincibilityEnabled: boolean) => {
  const { player, enemies, blocks } = state;
  state.projectiles = state.projectiles.filter((p: Projectile) => {
    p.pos.x += p.vel.x;
    p.pos.y += p.vel.y;
    // Imported GRAVITY fixed these errors
    if (p.isBoulder) p.vel.y += GRAVITY;
    if (p.isMethBarrel) { p.vel.y += GRAVITY; if (state.frame % 3 === 0) helpers.addParticle({ pos: { ...p.pos }, vel: { x: (Math.random()-0.5)*2, y: -Math.random()*4 }, life: 20, color: PARTICLE_PALETTES.METH[Math.floor(Math.random()*PARTICLE_PALETTES.METH.length)], size: 5 }); }

    if (p.owner === 'enemy' && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
      if (player.invincibilityTimer <= 0 && !invincibilityEnabled) {
        player.health -= p.damage;
        if (player.health > 0) {
          player.invincibilityTimer = 60;
          player.pushbackTimer = 20;
          player.vel.x = p.vel.x > 0 ? 15 : -15;
          player.vel.y = -5;
          // Interface now includes speakVulgarity
          helpers.speakVulgarity('hurt');
        }
      }
      return false;
    }

    if (p.owner === 'player') {
      for (const e of enemies) {
        if (e.health > 0 && p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x && p.pos.y < e.pos.y + e.height && p.pos.y + p.height > e.pos.y) {
          if (e.type === 'boss') {
            if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
              const dmg = BossLogic.getBossDamage(e, state.stageId, player.currentWeapon, p);
              const isW = BossLogic.checkIsWeakness(state.stageId, player.currentWeapon, p);
              e.health -= dmg; e.hitCooldown = 60;
              helpers.spawnDamageNumber(e.pos, dmg, isW);
              if (p.isIce) e.frozenTimer = SHOTGUN_FREEZE_TIME;
              if (e.health <= 0) helpers.triggerBossDeath(e, player.facing, isW);
            }
          } else {
            e.health -= p.damage;
            helpers.spawnDamageNumber(e.pos, p.damage);
            if (p.isIce) e.frozenTimer = SHOTGUN_FREEZE_TIME;
            if (e.health <= 0) {
              e.isBlownAway = true;
              e.vel = { x: p.vel.x * 0.5, y: -5 };
              player.killSatisfactionTimer = 60;
              if (p.isIce) helpers.spawnIceShatter(e.pos);
            }
          }
          if (!p.isBoulder && !p.isTsunami) return false;
        }
      }
    }

    if (p.isBoulder) {
      for (const b of blocks) {
        if (b.type !== 'pit' && p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) {
          if (p.pos.y + p.height - p.vel.y <= b.y) {
            p.pos.y = b.y - p.height; p.vel.y = -p.vel.y * 0.6;
            if (Math.abs(p.vel.y) < 1) p.vel.y = 0;
            if (p.owner === 'player') helpers.setScreenShake(5);
          } else {
            helpers.spawnExplosion(p.pos, PARTICLE_PALETTES.ROCK[0], 20);
            // Interface now includes spawnBoulderShrapnel
            if (p.owner === 'player') helpers.spawnBoulderShrapnel(p.pos, 12, p.vel.x > 0 ? 1 : -1);
            return false;
          }
        }
      }
    }

    if (p.isIce && p.owner === 'player') {
      for (const b of blocks) {
        if (b.type !== 'pit' && p.pos.x < b.x + b.w && p.pos.x + p.width > b.x && p.pos.y < b.y + b.h && p.pos.y + p.height > b.y) {
          helpers.spawnIceShatter(p.pos); return false;
        }
      }
    }

    if (p.isMethBarrel && p.health <= 0) {
       // Interface now includes spawnMethExplosion
       helpers.spawnMethExplosion(p.pos, 40);
       helpers.setScreenShake(15);
       return false;
    }

    if (p.life !== undefined) { p.life--; return p.life > 0; }
    return p.pos.x > state.camera.x - 1000 && p.pos.x < state.camera.x + 2000;
  });
};

export const updateEnemies = (state: any, helpers: WeaponHelpers, invincibilityEnabled: boolean) => {
  const { player, enemies, blocks } = state;
  enemies.forEach((e: Enemy) => {
    if (e.health <= 0) return;
    if (e.frozenTimer && e.frozenTimer > 0) { 
      e.frozenTimer--; 
      return; 
    }
    if (e.type === 'boss') return;

    if (e.enemyType === 'flyer') {
      e.pos.x += e.vel.x; e.pos.y += e.vel.y;
      if (Math.abs(e.pos.x - e.initialX) > e.patrolRange) e.vel.x *= -1;
    } else if (e.enemyType === 'tank') {
      if (e.behavior === 'patrol') {
        if (e.pauseTimer && e.pauseTimer > 0) {
          e.pauseTimer--;
        } else {
          e.vel.x = -4; e.pos.x += e.vel.x;
          if (Math.random() < 0.01) e.pauseTimer = 60;
        }
      }
    }

    if (e.behavior === 'shoot') {
      e.shootTimer++;
      const shootRate = e.enemyType === 'shield' ? 120 : (e.width > 60 ? 45 : 90);
      if (e.shootTimer >= shootRate) {
        e.shootTimer = 0;
        const dx = (player.pos.x + player.width/2) - (e.pos.x + e.width/2);
        const dy = (player.pos.y + player.height/2) - (e.pos.y + e.height/2);
        const dist = Math.sqrt(dx*dx + dy*dy);
        const speed = e.enemyType === 'shield' ? 6 : 8;
        helpers.addProjectile({ 
          id: `ep-${Date.now()}`, 
          pos: { x: e.pos.x + e.width/2, y: e.pos.y + e.height/2 }, 
          vel: { x: (dx/dist) * speed, y: (dy/dist) * speed }, 
          width: 12, height: 12, health: 1, maxHealth: 1, 
          type: 'projectile', damage: 15, owner: 'enemy' 
        });
      }
    }

    if (e.pos.x < player.pos.x + player.width && e.pos.x + e.width > player.pos.x && e.pos.y < player.pos.y + player.height && e.pos.y + e.height > player.pos.y) {
      if (player.invincibilityTimer <= 0 && !invincibilityEnabled && !player.isCharging && !player.isUppercutting) {
        player.health -= 20;
        if (player.health > 0) {
          player.invincibilityTimer = 60;
          player.pushbackTimer = 20;
          player.vel.x = player.pos.x < e.pos.x ? -15 : 15;
          player.vel.y = -5;
          // Interface now includes speakVulgarity
          helpers.speakVulgarity('hurt');
        }
      }
    }
  });

  // Handle special move collisions
  enemies.forEach((e: Enemy) => {
    if (e.health <= 0) return;
    if (player.isCharging || player.isUppercutting) {
      if (e.pos.x < player.pos.x + player.width && e.pos.x + e.width > player.pos.x && e.pos.y < player.pos.y + player.height && e.pos.y + e.height > player.pos.y) {
        if (!e.hitCooldown && !e.isBlownAway) {
          const isFrozen = e.frozenTimer && e.frozenTimer > 0;
          const baseDmg = player.isUppercutting ? ENEMY_UPPERCUT_DAMAGE : 50;
          const totalDmg = isFrozen ? baseDmg * 2 : baseDmg;

          if (isFrozen) {
            if (e.health - totalDmg <= 0) {
              // Lethal frozen hit: shatter
              e.health -= totalDmg;
              helpers.spawnIceShatter(e.pos);
            } else {
              // Non-lethal frozen hit: Meathead bounces back, enemy thaws
              player.vel.x = -player.facing * 12;
              player.vel.y = -5;
              player.isCharging = false;
              player.isUppercutting = false;
              e.frozenTimer = 0;
              helpers.spawnDamageNumber(e.pos, 0); 
              return; // Move to next enemy
            }
          } else {
            e.health -= totalDmg;
          }

          if (e.type === 'boss') {
             if (state.arenaLocked) {
               const bossDmg = BossLogic.getBossDamage(e, state.stageId, player.currentWeapon);
               const isW = BossLogic.checkIsWeakness(state.stageId, player.currentWeapon);
               const finalBossDmg = (player.isUppercutting ? BOSS_UPPERCUT_DAMAGE : BOSS_CHARGE_DAMAGE) * (isFrozen ? 2 : 1);
               e.health -= finalBossDmg;
               helpers.spawnDamageNumber(e.pos, finalBossDmg, isW);
               if (e.health <= 0) helpers.triggerBossDeath(e, player.facing, isW);
               e.hitCooldown = 60;
             }
          } else {
            helpers.spawnDamageNumber(e.pos, totalDmg);
            if (e.health <= 0) {
              e.isBlownAway = true;
              e.vel = { x: player.facing * 15, y: player.isUppercutting ? -20 : -10 };
              player.killSatisfactionTimer = 60;
              // Interface now includes speakVulgarity
              helpers.speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill');
            } else {
              e.hitCooldown = 30;
              e.vel.x = player.facing * 5;
            }
          }
        }
      }
    }
    if (e.hitCooldown && e.hitCooldown > 0) e.hitCooldown--;
  });
};

export const updateWeaponEffects = (state: any, helpers: WeaponHelpers, infiniteAmmo: boolean) => {
  const { player, tsunamiActive } = state;
  if (tsunamiActive) {
    state.tsunamiX += state.tsunamiDir * 15;
    const tRect = { x: state.tsunamiDir === 1 ? state.tsunamiX - 100 : state.tsunamiX, y: 0, w: 100, h: 600 };

    state.enemies.forEach((e: Enemy) => {
      if (e.health > 0 && e.pos.x < tRect.x + tRect.w && e.pos.x + e.width > tRect.x) {
        if (e.type === 'boss') {
          if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
            const dmg = BossLogic.getBossDamage(e, state.stageId, 'TSUNAMI');
            const isW = BossLogic.checkIsWeakness(state.stageId, 'TSUNAMI');
            e.health -= dmg; e.hitCooldown = 60;
            helpers.spawnDamageNumber(e.pos, dmg, isW);
            if (e.health <= 0) helpers.triggerBossDeath(e, player.facing, isW);
          }
        } else {
          e.health = 0; helpers.spawnDamageNumber(e.pos, 999);
          e.isBlownAway = true; e.vel = { x: state.tsunamiDir * 20, y: -15 };
          player.killSatisfactionTimer = 60;
          // Interface now includes speakVulgarity
          helpers.speakVulgarity('tsunami_kill');
        }
      }
    });

    state.projectiles.forEach((p: Projectile) => {
      if (p.owner === 'enemy' && p.pos.x < tRect.x + tRect.w && p.pos.x + p.width > tRect.x) p.health = 0;
    });

    if (state.frame % 2 === 0) {
      for (let i = 0; i < 15; i++) {
        helpers.addParticle({ 
          pos: { x: state.tsunamiX + (Math.random() - 0.5) * 50, y: Math.random() * 600 }, 
          vel: { x: state.tsunamiDir * (5 + Math.random() * 5), y: (Math.random() - 0.5) * 5 }, 
          life: 20 + Math.random() * 20, color: PARTICLE_PALETTES.WATER[Math.floor(Math.random() * PARTICLE_PALETTES.WATER.length)], size: 10 + Math.random() * 20 
        });
      }
    }

    if (state.tsunamiDir === 1 ? state.tsunamiX > state.camera.x + 900 : state.tsunamiX < state.camera.x - 100) {
      state.tsunamiActive = false;
    }
  }

  if (player.currentWeapon === 'TASER' && player.isTasing) {
    if (!infiniteAmmo) player.weaponAmmo['TASER'] -= 5;
    if (player.weaponAmmo['TASER'] <= 0) { player.isTasing = false; player.weaponAmmo['TASER'] = 0; return; }

    player.taserTimer++;
    if (state.frame % 3 === 0) {
      const pMidX = player.pos.x + player.width/2, pMidY = player.pos.y + player.height/2;
      let targetPos: Vector2 | null = null;
      let targetEntity: Enemy | Projectile | null = null;

      if (player.taserTargetId) {
        const e = state.enemies.find((en: Enemy) => en.id === player.taserTargetId && en.health > 0);
        if (e) { targetPos = { x: e.pos.x + e.width/2, y: e.pos.y + e.height/2 }; targetEntity = e; }
        else {
          const p = state.projectiles.find((pr: Projectile) => pr.id === player.taserTargetId && pr.health > 0);
          if (p) { targetPos = { x: p.pos.x + p.width/2, y: p.pos.y + p.height/2 }; targetEntity = p; }
        }
      }

      if (targetPos && targetEntity) {
         if (state.frame % 10 === 0) {
            if ('enemyType' in targetEntity) {
               const e = targetEntity as Enemy;
               if (e.type === 'boss') {
                  if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
                    const dmg = BossLogic.getBossDamage(e, state.stageId, 'TASER');
                    e.health -= dmg; e.hitCooldown = 15; helpers.spawnDamageNumber(e.pos, dmg);
                    if (e.health <= 0) helpers.triggerBossDeath(e, player.facing, false);
                  }
               } else {
                  e.health -= 3; e.isTased = true;
                  if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: 0, y: -5 }; helpers.speakVulgarity('taser_kill'); }
               }
            } else {
               const p = targetEntity as Projectile;
               p.health -= 10;
            }
         }
      }
    }

    if (!state.mouse.down && !navigator.getGamepads()[0]?.buttons[2]?.pressed) player.isTasing = false;
  }
};

