    } as Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number },
    enemies: [] as Enemy[], projectiles: [] as Projectile[], pickups: [] as Pickup[], particles: [] as (Particle & { isWater?: boolean })[], damageNumbers: [] as DamageNumber[], blocks: [] as { x: number, y: number, w: number, h: number, type: string }[], camera: { x: 0, y: 0 }, bossSpawned: false, arenaLocked: false, doorOpenAmount: 0, doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done', frame: 0, playerLastVulgarity: "", playerVulgarityTimer: 0, bossLastVulgarity: "", bossVulgarityTimer: 0, voiceLineCooldown: 0, victoryString: "", deathString: "", deathTimer: 0, postVictoryTimer: 0, introTimer: 0, bossExplosionTimer: 0, bossExplosionPos: { x: 0, y: 0 }, tsunamiX: -1, tsunamiStartX: 0, tsunamiActive: false, tsunamiDir: 1, bossVolcanoes: [] as Volcano[], bossVolcanoTelegraphs: [] as Volcano[], bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[], bossSteamExplosions: [] as SteamExplosion[], victorWallSide: 0 as number, ernieVibrationTimer: 0, playerStunTimer: 0, screenShakeTimer: 0, shouldSyncWeapon: false, totalPullForceX: 0, stageId: stageId, keys: {} as Record<string, boolean>, mouse: { down: false }
