    for (let i = 0; i < 50; i++) { state.particles.push({ pos: { ...pos }, vel: { x: (Math.random() - 0.5) * 35, y: (Math.random() - 0.5) * 35 - 5 }, life: 80 + Math.random() * 60, color: colors[Math.floor(Math.random() * colors.length)], size: 4 + Math.random() * 15, isGlass: true }); }
