        width: 12, height: 12, health: 1, maxHealth: 1,
        type: 'projectile', damage: 60, owner: 'player', isShrapnel: true
      });
    }
  }, []);

  const spawnMethExplosion = useCallback((pos: Vector2, count: number = 40) => {
