    if (category === 'hurt') { if (state.arenaLocked && stageId && BOSS_DIALOGUE.HURT[stageId as keyof typeof BOSS_DIALOGUE.HURT]) pool = BOSS_DIALOGUE.HURT[stageId as keyof typeof BOSS_DIALOGUE.HURT]; else pool = VULGARITIES.HURT; }
    if (category === 'death') pool = VULGARITIES.DEATH;
