  }, [stageId]);

  const playGunSound = useCallback((type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current; if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      if (type === 'gun') { osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime); osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1); gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1); } 
      else if (type === 'ice') { osc.type = 'sine'; osc.frequency.setValueAtTime(800, ctx.currentTime); osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1); gain.gain.setValueAtTime(0.08, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15); } 
      else if (type === 'flame') { osc.type = 'triangle'; osc.frequency.setValueAtTime(40 + Math.random() * 40, ctx.currentTime); osc.frequency.linearRampToValueAtTime(120, ctx.currentTime + 0.05); gain.gain.setValueAtTime(0.03, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05); } 
      else if (type === 'tsunami') { osc.type = 'sine'; osc.frequency.setValueAtTime(60, ctx.currentTime); osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 2); gain.gain.setValueAtTime(0.2, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 2.1); }
      else if (type === 'dart') { osc.type = 'square'; osc.frequency.setValueAtTime(2200, ctx.currentTime); osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.05); gain.gain.setValueAtTime(0.02, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06); }
      else if (type === 'horn') { osc.type = 'sawtooth'; osc.frequency.setValueAtTime(110, ctx.currentTime); osc.frequency.setValueAtTime(115, ctx.currentTime + 0.2); gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1.0); }
      osc.connect(gain); gain.connect(ctx.destination); osc.start(); osc.stop(ctx.currentTime + 2.5);
    } catch (e) {}
  }, []);

  const weaponHelpers: WeaponLogic.WeaponHelpers = {
    addProjectile: (p) => gameStateRef.current.projectiles.push(p),
    addParticle: (p) => gameStateRef.current.particles.push(p),
    playGunSound,
    spawnExplosion,
    spawnDamageNumber,
    spawnGlassShatter,
    spawnIceShatter,
    spawnSteamExplosionParticles,
    spawnDeathShower,
    spawnPickup: (pos) => {}, 
    speakVulgarity,
    setScreenShake: (dur) => { gameStateRef.current.screenShakeTimer = dur; },
    triggerBossDeath: (boss, facing, weak) => { BossLogic.triggerBossDeath(boss, facing, weak, stageId, currentWeapon, gameStateRef.current, bossHelpers); },
    spawnRockShatter,
    spawnBoulderShrapnel,
    spawnMethExplosion
  };

  const bossHelpers: BossLogic.BossHelpers = {
    ...weaponHelpers,
    onBossDeath,
    setBossVulgarity: (text, dur) => { gameStateRef.current.bossLastVulgarity = text; gameStateRef.current.bossVulgarityTimer = dur; },
    setErnieVibration: (dur) => { gameStateRef.current.ernieVibrationTimer = dur; },
    setPlayerStun: (dur) => { gameStateRef.current.playerStunTimer = dur; },
    addVolcano: (v) => gameStateRef.current.bossVolcanoes.push(v),
    clearVolcanoes: () => gameStateRef.current.bossVolcanoes = [],
    addVolcanoTelegraph: (v) => gameStateRef.current.bossVolcanoTelegraphs.push(v),
    clearVolcanoTelegraphs: () => gameStateRef.current.bossVolcanoTelegraphs = [],
    addPoopTelegraph: (t) => gameStateRef.current.bossPoopTelegraphs.push(t),
    clearPoopTelegraphs: () => gameStateRef.current.bossPoopTelegraphs = [],
    setVictorWallSide: (side) => gameStateRef.current.victorWallSide = side,
    setTsunamiActive: (active) => gameStateRef.current.tsunamiActive = active
  };

  const buildLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.blocks = [
      { x: 0, y: 550, w: 7200, h: 50, type: 'ground' },
      { x: 7200, y: 550, w: 800, h: 50, type: 'ground' },
      { x: 7200, y: 100, w: 40, h: 450, type: 'door' }
    ];

    // Platforms
    for (let i = 1; i < 15; i++) {
      state.blocks.push({ x: i * 500, y: 400 - (i % 3) * 50, w: 200, h: 20, type: 'platform' });
    }

    // Boss area platforms
    state.blocks.push({ x: 7400, y: 400, w: 150, h: 20, type: 'platform' });
    state.blocks.push({ x: 7700, y: 400, w: 150, h: 20, type: 'platform' });

    // Enemies
    state.enemies = [];
    for (let i = 1; i < 20; i++) {
      const ex = 800 + i * 350;
      state.enemies.push({
        id: `e-${i}`,
        pos: { x: ex, y: 450 },
        vel: { x: -2, y: 0 },
        width: 40, height: 60, health: 50, maxHealth: 50, type: 'enemy',
        enemyType: 'tank', behavior: 'patrol', patrolRange: 100, initialX: ex, shootTimer: 0
      });
    }
  }, []);

  useEffect(() => {
    if (status === GameStatus.LEVEL_INTRO) {
      buildLevel();
      gameStateRef.current.player.pos = { x: 150, y: 100 };
      gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
      gameStateRef.current.camera.x = 0;
      gameStateRef.current.bossSpawned = false;
      gameStateRef.current.arenaLocked = false;
      gameStateRef.current.doorState = 'closed';
      gameStateRef.current.doorOpenAmount = 0;
      onIntroComplete();
    }
  }, [status, buildLevel, onIntroComplete]);

  useEffect(() => {
    let frameId: number;
    const update = () => {
      const state = gameStateRef.current;
      const { player, keys, mouse } = state;

      if (status === GameStatus.PLAYING) {
        state.frame++;
        if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
        if (state.playerVulgarityTimer > 0) state.playerVulgarityTimer--;
        if (state.bossVulgarityTimer > 0) state.bossVulgarityTimer--;
        if (state.screenShakeTimer > 0) state.screenShakeTimer--;
        if (state.playerStunTimer > 0) state.playerStunTimer--;

        // Player movement
        if (!player.isCharging && !player.isUppercutting && state.playerStunTimer <= 0) {
          const moveX = (keys['d'] || keys['arrowright'] ? 1 : 0) - (keys['a'] || keys['arrowleft'] ? 1 : 0);
          player.vel.x = moveX * PLAYER_SPEED;
          if (moveX !== 0) player.facing = moveX as 1 | -1;

          if ((keys[' '] || keys['w'] || keys['arrowup']) && player.isGrounded) {
            player.vel.y = PLAYER_JUMP_FORCE;
            player.isGrounded = false;
          }
        }

        // Flamethrower range charging
        if (currentWeapon === 'FLAMETHROWER' && mouse.down) {
          player.flamethrowerCharge = (player.flamethrowerCharge || 0) + 1;
        } else {
          player.flamethrowerCharge = 0;
        }

        // Special Moves (Shoulder Charge / Uppercut)
        if (keys['shift'] && player.chargeInputReleased && player.specialCharges > 0 && !player.isCharging && !player.isUppercutting) {
          if (keys['w'] || keys['arrowup']) {
            player.isUppercutting = true;
            player.vel.y = UPPERCUT_FORCE;
            player.chargeDuration = 25;
          } else {
            player.isCharging = true;
            player.vel.x = player.facing * CHARGE_SPEED;
            player.chargeDuration = CHARGE_DURATION;
          }
          player.specialCharges--;
          player.chargeInputReleased = false;
        }
        if (!keys['shift']) player.chargeInputReleased = true;

        if (player.isCharging) {
          player.chargeDuration--;
          player.vel.x = player.facing * CHARGE_SPEED;
          if (player.chargeDuration <= 0) player.isCharging = false;
        }
        if (player.isUppercutting) {
          player.chargeDuration--;
          if (player.chargeDuration <= 0) player.isUppercutting = false;
        }

        // Gravity & Physics
        player.vel.y += GRAVITY;
        player.pos.x += player.vel.x;
        player.pos.y += player.vel.y;

        // Special charge regen
        if (player.specialCharges < MAX_SPECIAL_CHARGES) {
          player.specialChargeTimer++;
          if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) {
            player.specialCharges++;
            player.specialChargeTimer = 0;
          }
        }

        // Weapon firing
        if (player.shootCooldown > 0) player.shootCooldown--;
        if (mouse.down && player.shootCooldown <= 0) {
          WeaponLogic.fireWeapon(player, state, weaponHelpers, keys['w'] || keys['arrowup'], keys['s'] || keys['arrowdown'], infiniteAmmoEnabled);
        }

        // Collision detection
        player.isGrounded = false;
        for (const b of state.blocks) {
          if (b.type === 'door' && state.doorState === 'opening') continue;
          if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
            if (player.vel.y > 0 && player.pos.y + player.height - player.vel.y <= b.y) {
              player.pos.y = b.y - player.height;
              player.vel.y = 0;
              player.isGrounded = true;
            } else if (player.vel.y < 0 && player.pos.y - player.vel.y >= b.y + b.h) {
              player.pos.y = b.y + b.h;
              player.vel.y = 0;
            } else if (player.vel.x > 0 && player.pos.x + player.width - player.vel.x <= b.x) {
              player.pos.x = b.x - player.width;
            } else if (player.vel.x < 0 && player.pos.x - player.vel.x >= b.x + b.w) {
              player.pos.x = b.x + b.w;
            }
          }
        }

        // Arena lock logic
        if (player.pos.x > BOSS_DOOR_X && !state.arenaLocked) {
          state.arenaLocked = true;
          onBossEncounter();
          if (!state.bossSpawned) {
            state.bossSpawned = true;
            state.enemies.push({
              id: 'boss', pos: { x: 7800, y: 450 }, vel: { x: 0, y: 0 }, width: 80, height: 100, health: 1000, maxHealth: 1000, type: 'boss',
              enemyType: 'tank', behavior: 'patrol', patrolRange: 0, initialX: 7800, shootTimer: 0
            });
          }
        }

        // Scroll camera
        if (!state.arenaLocked) {
          state.camera.x = Math.max(0, Math.min(BOSS_DOOR_X - CANVAS_WIDTH + 200, player.pos.x - 300));
        } else {
          state.camera.x = BOSS_DOOR_X;
        }

        // Updates
        WeaponLogic.updateProjectiles(state, weaponHelpers, invincibilityEnabled);
        WeaponLogic.updateEnemies(state, weaponHelpers, invincibilityEnabled);
        WeaponLogic.updateWeaponEffects(state, weaponHelpers, infiniteAmmoEnabled);

        state.enemies.forEach(e => {
          if (e.type === 'boss') BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, state, bossHelpers);
        });

        state.particles = state.particles.filter(p => { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.vel.y += 0.2; p.life--; return p.life > 0; });
        state.damageNumbers = state.damageNumbers.filter(d => { d.pos.y += d.vel.y; d.life--; return d.life > 0; });

        onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, player.currentWeapon);
      }

      draw();
      frameId = requestAnimationFrame(update);
    };

    const draw = () => {
      const ctx = canvasRef.current?.getContext('2d');
      if (!ctx) return;
      const state = gameStateRef.current;
      const { player, camera } = state;

      ctx.save();
      if (state.screenShakeTimer > 0) ctx.translate((Math.random() - 0.5) * 10, (Math.random() - 0.5) * 10);
      ctx.translate(-camera.x, -camera.y);

      // BG
      ctx.fillStyle = '#111';
      ctx.fillRect(camera.x, camera.y, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Blocks
      state.blocks.forEach(b => {
        ctx.fillStyle = b.type === 'door' ? '#444' : '#333';
        ctx.fillRect(b.x, b.y, b.w, b.h);
      });

      // Entities
      state.enemies.forEach(e => {
        if (e.health <= 0 && !e.isBlownAway) return;
        if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, state.frame);
        else {
          ctx.fillStyle = e.frozenTimer ? '#0FF' : '#A0A';
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        }
      });

      // Player
      ctx.fillStyle = player.isCharging || player.isUppercutting ? '#FF0' : '#F84';
      ctx.fillRect(player.pos.x, player.pos.y, player.width, player.height);

      // Projectiles
      state.projectiles.forEach(p => {
        ctx.fillStyle = p.owner === 'player' ? '#FF0' : '#F00';
        ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
      });

      // Particles
      state.particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });

      // Damage
      state.damageNumbers.forEach(d => {
        ctx.fillStyle = d.isCritical ? '#FF0' : '#FFF';
        ctx.font = '12px "Press Start 2P"';
        ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
      });

      // Speech bubbles
      if (state.playerVulgarityTimer > 0) {
        ctx.fillStyle = 'white';
        ctx.font = '10px "Press Start 2P"';
        ctx.fillText(state.playerLastVulgarity, player.pos.x, player.pos.y - 10);
      }

      ctx.restore();
    };

    frameId = requestAnimationFrame(update);
    return () => cancelAnimationFrame(frameId);
  }, [status, stageId, currentWeapon, infiniteAmmoEnabled, invincibilityEnabled, onPlayerUpdate, onBossEncounter]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} />;
};

